    explanation: '同じ抵抗値のものを n 本並列に接続すると、合成抵抗は R÷n になる。電流の通り道が n 本に増えるため、全体として電流が流れやすくなると考えるとよい。\n式：R合＝R×R÷(R＋R)\n計算：R²÷2R\n答え：R合＝R÷2\n逆に、同じ抵抗を n 本直列にすると合成抵抗は nR になる。試験では 10 Ω を3本並列にしたら何 Ω か、といった形で問われる。この場合は 10÷3＝3.33 Ω である。並列合成抵抗は必ず最小の抵抗値より小さくなるという性質を使うと、選択肢のうち R 以上のものはすべて消去できる。実務でも、細い電線を並列にして許容電流を確保する考え方の基礎になる。\n【図解】同じ抵抗 R を n 本つないだとき\n　本数｜直列の合成｜並列の合成\n　2本｜2R｜R÷2★\n　3本｜3R｜R÷3\n　4本｜4R｜R÷4\n　⇒ 直列は本数倍、並列は本数分の1になる\n　⚠ 抵抗値が異なる場合はこの単純な形は使えない',
