    correctKey: 'A',
    explanation: '直並列回路の応用問題では、合成、全電流、分流の3段階で処理する。\n手順1（並列部）：10×15÷(10＋15)＝150÷25＝6 Ω\n手順2（全合成）：6＋6＋8＝20 Ω\n手順3（全電流）：I＝100÷20＝5 A\n手順4（分流）：I10＝5×15÷(10＋15)＝75÷25＝3 A\n答え：3 A\n検算する。並列部に加わる電圧は 5×6＝30 V なので、10 Ω には 30÷10＝3 A、15 Ω には 30÷15＝2 A が流れ、合計 5 A で全電流と一致する。分流の式では相手側の抵抗が分子に来ることを忘れないこと。抵抗が小さいほうに多くの電流が流れるので、10 Ω 側の 3 A が 15 Ω 側の 2 A より大きいのは妥当である。\n【図解】各部の電圧と電流（電源 100 V、全電流 5 A）\n　部分｜抵抗｜電圧降下\n　直列の 6 Ω｜6 Ω｜30 V\n　並列部（10と15）｜6 Ω｜30 V\n　直列の 8 Ω｜8 Ω｜40 V\n　⇒ 電圧降下の合計 30＋30＋40＝100 V で電源電圧と一致\n　⚠ 並列部の電圧 30 V から各枝の電流を出すと確実',
