    correctKey: 'D',
    explanation: '直列回路では電流がどこでも同じなので、まず合成抵抗から全電流を求め、次に着目する抵抗の電圧降下を計算する。\n手順1：合成抵抗 R＝2＋3＋5＝10 Ω\n手順2：電流 I＝100÷10＝10 A\n手順3：3 Ω の電圧降下 V＝10×3＝30 V\n答え：30 V\n各抵抗の電圧降下は 2 Ω が 20 V、3 Ω が 30 V、5 Ω が 50 V であり、合計 100 V で電源電圧と一致する。直列回路では電圧は抵抗値に比例して分配されるので、2 対 3 対 5 の比で 100 V が分かれると考えても同じ結果になる。この比の考え方を使えば、電流を計算しなくても 100×3÷10＝30 V とすぐ求められる。試験では時間が限られるので、比で処理できる問題は比で解くとよい。\n【図解】直列3抵抗の電圧配分（100 V、全電流 10 A）\n　抵抗｜比｜電圧降下\n　2 Ω｜2｜20 V\n　3 Ω｜3｜30 V★\n　5 Ω｜5｜50 V\n　⇒ 合計 100 V で電源電圧に一致することを必ず確認\n　⚠ 電流はどの抵抗でも 10 A で共通、変わるのは電圧',
