    correctKey: 'A',
    explanation: '電力量は消費した電気エネルギーの総量であり、電力と使用時間の積で表される。実用単位は kW·h（キロワット時）である。\n式：W＝P×t\n代入：W＝0.5 kW×4 h\n答え：W＝2 kW·h\nW 単位のまま計算すると 500 W×4 h＝2000 W·h であり、1000 で割って 2 kW·h となる。どちらの手順でも結果は同じだが、単位換算を先に行うほうが桁の誤りが少ない。電力 [W] は瞬間的な消費の勢い、電力量 [kW·h] は積み重ねた総量である。電気料金は電力量に対して課金される。SI 単位ではエネルギーは J（ジュール）で表され、1 W·s＝1 J なので 1 kW·h＝1000×3600＝3.6×10⁶ J である。この換算も出題されることがある。\n【図解】電力と電力量の違い\n　項目｜電力｜電力量\n　意味｜消費の勢い｜消費の総量\n　単位｜W、kW｜W·h、kW·h、J\n　本問の値｜500 W＝0.5 kW｜0.5×4＝2 kW·h★\n　⇒ 電気料金の対象になるのは電力量のほう\n　⚠ W と kW を混ぜたまま掛けると1000倍の誤りになる',
