    explanation: '抵抗に電流が流れると熱が発生する。これをジュール熱といい、その熱量は電流の 2 乗と抵抗と時間の積に比例する。時間は必ず秒に直してから計算する。\n式：Q＝I²×R×t\n代入：Q＝2²×10×(5×60)＝4×10×300\n答え：Q＝12000 J＝12 kJ\n電力から求めても同じである。P＝I²R＝4×10＝40 W なので、Q＝Pt＝40×300＝12000 J となる。1 W の電力で 1 秒間に 1 J のエネルギーが消費されるという関係が基本である。時間の単位換算を忘れて分のまま計算すると 200 分の 1 の値になってしまうので、まず秒に直すことを習慣にする。ジュール熱は電線の発熱や電熱器の発熱の基礎であり、電流の 2 乗に比例するため、電流が大きい回路ほど発熱が急激に増える。\n【図解】ジュール熱の計算（2 A、10 Ω、5 分）\n　段階｜式｜結果\n　時間の換算｜5×60｜300 s\n　電力｜I²×R｜4×10＝40 W\n　熱量｜P×t｜40×300＝12000 J★\n　⇒ 12000 J＝12 kJ。電流が2倍なら熱量は4倍\n　⚠ 時間を分のまま代入すると答えが大きく狂う',
