    explanation: '水を温めるのに必要な熱量は、比熱と質量と温度上昇の積で求める。水 1 L の質量は 1 kg である。\n手順1（必要熱量）：Q＝4.2×2×(60－20)＝4.2×2×40＝336 kJ\n手順2（有効な電力）：P有効＝1×0.8＝0.8 kW\n手順3（時間）：t＝336÷0.8＝420 s\n答え：420 s＝7 分\n電熱器が消費する電気エネルギーのうち、実際に水を温めるのに使われるのは熱効率の分だけである。残りは容器や周囲の空気を温めるなどして失われる。したがって効率が悪いほど時間がかかる。効率 100 % なら 336÷1＝336 秒＝5 分 36 秒だが、80 % では 420 秒となる。単位を kJ と kW でそろえると、kJ÷kW＝秒 となり計算が簡単になる。この単位のそろえ方が計算を速くするコツである。\n【図解】電熱器の計算手順\n　段階｜式｜結果\n　必要熱量｜比熱×質量×温度差｜4.2×2×40＝336 kJ\n　有効電力｜定格×効率｜1×0.8＝0.8 kW\n　所要時間｜熱量÷有効電力｜336÷0.8＝420 s★\n　⇒ kJ を kW で割ると秒が得られる\n　⚠ 効率は割るのではなく電力に掛ける',
    difficulty: 'advanced',
