    correctKey: 'A',
    explanation: '抵抗が一定のとき、消費電力は P＝V²÷R で表されるので電圧の 2 乗に比例する。\n式：P比＝(V後÷V前)²\n代入：P比＝(90÷100)²＝0.9²\n答え：P比＝0.81＝81 %\n電流も同時に変化する。I＝V÷R より電流は電圧に比例するので 90 % になる。電力は電圧と電流の積なので 0.9×0.9＝0.81 となり、やはり 81 % である。この関係は実務上とても重要で、配線の電圧降下によって電熱器の能力が想定以上に落ちる原因になる。たとえば電圧が 10 % 下がるだけで能力は約 19 % も落ちる。だからこそ内線規程では幹線と分岐回路の電圧降下を標準で 2 % 以内に抑えるよう定めている。\n【図解】電圧が変わったときの変化（抵抗一定）\n　量｜比例関係｜90 V のとき\n　電流 I｜電圧に比例｜90 %\n　電力 P｜電圧の2乗に比例｜81 %★\n　熱量 Q｜電力に比例｜81 %\n　⇒ 電圧 10 % 低下で能力は約 19 % 低下する\n　⚠ 電力も 90 % と考えるのが典型的な誤り',
