    explanation: '抵抗の式 R＝ρL÷A において、長さと断面積の両方が変わる場合は、それぞれの効果を掛け合わせる。\n手順1（長さ）：2 倍になるので抵抗は 2 倍の方向\n手順2（直径）：2 倍なので断面積は 2²＝4 倍、抵抗は 4 分の 1 の方向\n手順3（合成）：2×(1÷4)＝1÷2\n答え：2 分の 1\n数値で確認する。もとの電線を ρ＝1.7×10⁻⁸ Ω·m、L＝10 m、直径 2 mm（断面積 3.14 mm²）とすると、R＝1.7×10⁻⁸×10÷(3.14×10⁻⁶)＝0.054 Ω である。長さ 20 m、直径 4 mm（断面積 12.56 mm²）にすると R＝1.7×10⁻⁸×20÷(12.56×10⁻⁶)＝0.027 Ω となり、ちょうど半分になる。複数の条件が同時に変わる問題では、条件ごとに倍率を出して最後に掛け合わせるのが確実な解き方である。\n【図解】条件ごとの倍率と合成\n　変化した条件｜抵抗への効果｜倍率\n　長さ 2 倍｜比例｜×2\n　直径 2 倍｜断面積 4 倍で反比例｜×(1÷4)\n　合成｜2×0.25｜0.5 倍★\n　⇒ 条件ごとの倍率を掛け合わせれば確実\n　⚠ 直径と断面積の倍率を同じにしてはいけない',
