    explanation: '金属導体では、温度が上がると金属原子の熱振動が激しくなり、自由電子の移動が妨げられる。そのため電気抵抗は大きくなる。この性質を正の温度係数という。一方、半導体や絶縁体では温度が上がると電気を運ぶ自由電子が増えるため抵抗が小さくなる。これを負の温度係数という。\n金属の抵抗は、温度 t ℃ における抵抗を Rt、0 ℃ における抵抗を R0、温度係数を α とすると Rt＝R0×(1＋αt) で表される。銅の温度係数はおよそ 0.004 で、温度が 1 ℃ 上がるごとに抵抗が約 0.4 % 増える。したがって 20 ℃ から 70 ℃ へ 50 ℃ 上がると抵抗は約 20 % 増加する。電線に大電流が流れて温度が上がると抵抗が増え、電圧降下と発熱がさらに増えるという悪循環になるため、許容電流を守ることが重要である。\n【図解】温度が上がったときの抵抗の変化\n　材料の種類｜温度係数｜抵抗の変化\n　金属（銅、アルミ）｜正｜大きくなる★\n　半導体（シリコン）｜負｜小さくなる\n　絶縁体（ゴム、磁器）｜負｜小さくなる\n　⇒ 金属だけが温度上昇で抵抗が増えると覚える\n　⚠ すべての物質で同じ向きに変化するわけではない',
