    explanation: '電熱線の抵抗は長さに比例するので、長さを 2 分の 1 にすれば抵抗も 2 分の 1 になる。電圧が一定のときの消費電力は P＝V²÷R で表され、抵抗に反比例する。\n手順1（抵抗）：R2＝R1÷2\n手順2（電力）：P2＝V²÷R2＝V²÷(R1÷2)＝2×(V²÷R1)\n答え：2 倍\n数値で確認する。もとが 100 V、20 Ω なら P＝10000÷20＝500 W である。長さを半分にして 10 Ω になると P＝10000÷10＝1000 W となり、確かに 2 倍である。電流も 5 A から 10 A に 2 倍になる。\n実務では、電熱線を短くすると発熱が急増して過熱や焼損の原因となる。また回路の電流が増えるため過電流遮断器が動作する可能性もある。安易に電熱線を切り詰めてはならない理由がここにある。\n【図解】ニクロム線の長さを半分にしたとき（100 V）\n　量｜もとの状態｜半分にした後\n　抵抗｜20 Ω｜10 Ω\n　電流｜5 A｜10 A\n　電力｜500 W｜1000 W★\n　⇒ 電圧一定なら電力は抵抗に反比例する\n　⚠ 短くすれば電力が減ると考えるのは逆',
