    correctKey: 'C',
    explanation: 'コンデンサは電荷を蓄える素子であり、その能力を表すのが静電容量 C で、単位は F（ファラド）である。1 F は 1 V の電圧を加えたときに 1 C の電荷を蓄える容量を意味する。1 F は非常に大きな値なので、実用上は μF（マイクロファラド、10⁻⁶ F）や pF（ピコファラド、10⁻¹² F）が使われる。\n式：Q＝C×V\n例：C＝20 μF に V＝100 V を加えると\n代入：Q＝20×10⁻⁶×100\n答え：Q＝2×10⁻³ C＝2 mC\n混同しやすい単位を整理しておく。電荷は C（クーロン）、インダクタンスは H（ヘンリー）、磁束は Wb（ウェーバ）、磁束密度は T（テスラ）である。記号の C が静電容量と電荷の両方に使われるが、単位としての C は電荷を表す点に注意する。\n【図解】まぎらわしい単位の整理\n　量｜記号｜単位\n　静電容量｜C｜F（ファラド）★\n　電荷（電気量）｜Q｜C（クーロン）\n　インダクタンス｜L｜H（ヘンリー）\n　⇒ 量の記号 C と単位の C は別物である\n　⚠ 静電容量の単位を C と答える誤りが多い',
