    correctKey: 'C',
    explanation: '同じ静電容量 C のコンデンサを n 個直列に接続すると、合成静電容量は C÷n になる。逆に n 個並列に接続すると nC になる。抵抗の場合と直列・並列が入れ替わる点に注意する。\n式：C合＝C×C÷(C＋C)\n計算：C²÷2C\n答え：C合＝C÷2\n直列にすると極板の間隔が広がったのと同じ効果になり、容量が減る。一方で、各コンデンサに加わる電圧は半分になるので、耐圧の面では有利になる。たとえば耐圧 200 V のコンデンサを 2 個直列にすれば 400 V まで使える（容量は半分になる）。\n並列にすると容量は 2C と増えるが、耐圧はそのままである。用途に応じて接続を選ぶ必要がある。\n【図解】同じ容量 C を n 個つないだとき\n　個数｜直列の合成｜並列の合成\n　2 個｜C÷2★｜2C\n　3 個｜C÷3｜3C\n　4 個｜C÷4｜4C\n　⇒ 抵抗の直並列とちょうど逆の形になる\n　⚠ 直列で 2C とするのは抵抗との混同',
