    explanation: '正弦波交流の実効値は、最大値を √2（約 1.41）で割って求める。\n式：実効値＝最大値÷√2\n代入：実効値＝141÷1.41\n答え：実効値＝100 V\nこの関係から、家庭のコンセントの 100 V（実効値）は、瞬間的には最大 141 V に達していることがわかる。絶縁材料の耐電圧を検討するときは、この最大値を考慮する必要がある。\n同じ交流の平均値は 141×2÷π＝141×0.637＝約 90 V である。実効値の 100 V とは異なるので混同しないこと。3 つの値の大小関係は、最大値 141 V が最も大きく、次に実効値 100 V、最後に平均値 90 V となる。選択肢にこの 3 つが並んでいる問題が多いので、何を問われているかを正確に読み取ることが重要である。\n【図解】最大値 141 V の正弦波\n　代表値｜計算｜値\n　最大値｜与えられた値｜141 V\n　実効値｜141÷1.41｜100 V★\n　平均値｜141×0.637｜約 90 V\n　⇒ 交流計器が示すのは通常は実効値である\n　⚠ 平均値 90 V を実効値と誤って選ばないこと',
