    explanation: '正弦波交流の平均値は、半周期分について瞬時値を平均した値と定義される。1 周期全体では正と負が打ち消し合って 0 になるため、半周期で考える。正弦波の場合、平均値は最大値の 2÷π 倍になる。\n式：平均値＝最大値×2÷π\n代入：平均値＝141×2÷3.14＝141×0.637\n答え：平均値＝約 90 V\n実効値 100 V と平均値 90 V は近い値だが別の量である。両者の比 100÷90＝1.11 を波形率といい、正弦波では約 1.11 になる。また、最大値と実効値の比 141÷100＝1.41 を波高率という。\n整流形の計器は平均値に応答するが、目盛は正弦波の実効値に換算して振ってある。そのため、ひずんだ波形の交流を測ると誤差が生じる。この点も出題されることがある。\n【図解】正弦波の代表値と比\n　項目｜定義｜正弦波での値\n　波高率｜最大値÷実効値｜約 1.41\n　波形率｜実効値÷平均値｜約 1.11\n　平均値｜最大値×2÷π｜約 0.637 倍★\n　⇒ 大小は最大値、実効値、平均値の順\n　⚠ 平均値と実効値を取り違える誤りが多い',
