    explanation: '日本の商用電源の周波数は、東日本がおもに 50 Hz、西日本がおもに 60 Hz である。境界は静岡県の富士川と新潟県の糸魚川を結ぶ付近にある。明治期に東京がドイツ製の 50 Hz 発電機を、大阪がアメリカ製の 60 Hz 発電機を導入したことに由来する。\n周波数が異なると、機器の動作に影響が出る。誘導電動機の同期速度は Ns＝120f÷p [min⁻¹] で表され、周波数に比例する。極数 4 の電動機では、50 Hz で 1500 min⁻¹、60 Hz で 1800 min⁻¹ となる。\n式：Ns＝120×f÷p\n代入（50 Hz、4 極）：120×50÷4\n答え：Ns＝1500 min⁻¹\nまた、変圧器やコイルのリアクタンスも周波数によって変わるため、地域をまたいで機器を移設する際は周波数の確認が必要である。\n【図解】周波数による違い（4 極誘導電動機）\n　地域｜周波数｜同期速度\n　東日本｜50 Hz｜1500 min⁻¹★\n　西日本｜60 Hz｜1800 min⁻¹\n　式｜Ns＝120f÷p｜極数で割る\n　⇒ 周波数が高いほど回転速度も速くなる\n　⚠ 東西を逆に覚えないこと',
