    correctKey: 'D',
    explanation: 'Y 結線では線間電圧が相電圧の √3 倍なので、相電圧を求めるには線間電圧を √3 で割る。\n式：V相＝V線÷√3\n代入：V相＝200÷1.73\n答え：V相＝約 115 V\n低圧三相 200 V の配電では、各相にかかる電圧は約 115 V である。この値は、三相負荷の 1 相あたりの電流や消費電力を計算するときに必要になる。\n例として、各相 10 Ω の Y 結線負荷に線間 200 V を加えた場合、相電流は I相＝115÷10＝11.5 A である。Y 結線では線電流＝相電流なので線電流も 11.5 A になる。三相全体の消費電力は P＝3×I²×R＝3×11.5²×10＝3968 W である。P＝√3×V線×I線＝1.73×200×11.5＝3979 W とほぼ一致する（端数処理の差）。\n【図解】線間 200 V の Y 結線（各相 10 Ω）\n　量｜計算｜結果\n　相電圧｜200÷1.73｜約 115 V★\n　相電流｜115÷10｜11.5 A\n　線電流｜相電流と同じ｜11.5 A\n　⇒ Y 結線の計算はまず相電圧を出すのが定石\n　⚠ 3 で割って 66.7 V とするのは誤り',
