    explanation: '三相電力の式 P＝√3×V×I×cosθ を電流について解く。\n式：I＝P÷(√3×V×cosθ)\n代入：I＝5500÷(1.73×200×0.8)\n計算（分母）：1.73×200＝346、346×0.8＝276.8\n答え：I＝5500÷276.8＝約 20 A\n分母を先にまとめて計算するのがコツである。三相 200 V、力率 0.8 の場合、分母は常に 276.8 になるので、有効電力を約 277 で割れば線電流が出ると覚えておくと速い。\n電動機の定格出力が kW で示されている場合、入力電力は効率でも割る必要がある。たとえば出力 5.5 kW、効率 0.85、力率 0.8 の電動機では、入力は 5.5÷0.85＝6.47 kW となり、線電流は 6470÷276.8＝23.4 A になる。問題文が出力を指すのか入力を指すのかを確認すること。\n【図解】三相電流の計算（200 V、力率 0.8）\n　段階｜計算｜結果\n　√3×V｜1.73×200｜346\n　分母｜346×0.8｜276.8\n　線電流｜5500÷276.8｜約 20 A★\n　⇒ 三相 200 V・力率 0.8 では分母は約 277\n　⚠ √3 を忘れると答えが 1.73 倍になる',
