    explanation: '電流計は、測定したい電流がそのまま流れるように回路に直列に接続する。電流計の内部抵抗はきわめて小さく作られており、回路に挿入しても電流をほとんど変化させない。\n逆に、電圧計は測定したい 2 点間に並列に接続する。電圧計の内部抵抗はきわめて大きく作られており、回路からほとんど電流を分岐させない。\n電流計を誤って負荷と並列に接続すると、内部抵抗が小さいため大電流が流れて短絡状態となり、電流計が焼損したり過電流遮断器が動作したりする。逆に電圧計を直列に接続すると、内部抵抗が大きいためほとんど電流が流れず、負荷が動作しない。\n測定範囲を拡大するには、電流計には分流器を並列に、電圧計には倍率器を直列に接続する。接続方法が計器本体と逆になる点に注意する。\n【図解】計器の接続方法と内部抵抗\n　計器｜接続方法｜内部抵抗\n　電流計｜負荷と直列★｜きわめて小さい\n　電圧計｜負荷と並列｜きわめて大きい\n　範囲拡大｜電流計は分流器を並列｜電圧計は倍率器を直列\n　⇒ 計器本体と範囲拡大器で接続方法が逆になる\n　⚠ 電流計の並列接続は短絡事故になり危険',
