    explanation: '倍率器の抵抗は、電圧計の内部抵抗に倍率から 1 を引いた値を掛けて求める。\n式：Rm＝r×(m－1)\n代入：Rm＝10×(5－1)＝10×4\n答え：Rm＝40 kΩ\n考え方を確認する。倍率器と電圧計は直列なので、加えた電圧は抵抗の比で分圧される。電圧計に加わるのが全体の 1÷m でなければならないので、r÷(r＋Rm)＝1÷m が成り立つ。これを解くと Rm＝r×(m－1) が得られる。\n本問では、全体の合成抵抗が 10＋40＝50 kΩ となり、電圧計にはその 10÷50＝5 分の 1 が加わる。したがって指示値を 5 倍すれば実際の電圧が読める。\n分流器の式 Rs＝r÷(m－1) と混同しやすい。倍率器は直列で掛け算、分流器は並列で割り算と対で覚える。\n【図解】倍率器の計算（r＝10 kΩ、m＝5）\n　項目｜式｜結果\n　倍率器の抵抗｜10×(5－1)｜40 kΩ★\n　全体の抵抗｜10＋40｜50 kΩ\n　電圧計の分担｜10÷50｜5 分の 1\n　⇒ 掛けるのは m ではなく m－1\n　⚠ 50 kΩ を選ぶ誤りが多い',
