    explanation: 'クランプ形漏れ電流計で漏えい電流を測定するときは、その回路のすべての電線を一括してクランプする。単相 2 線式なら 2 本、単相 3 線式なら 3 本、三相 3 線式なら 3 本すべてをはさむ。\n正常な状態では行きの電流と帰りの電流が等しいため、一括すると磁束が打ち消し合って計器は 0 を示す。絶縁不良があって大地へ電流が漏れていると、行きと帰りの差が生じ、その差が漏えい電流として測定される。この原理は漏電遮断器の零相変流器と同じである。\n電気設備技術基準では、絶縁抵抗の測定が困難な場合、漏えい電流が 1 mA 以下であれば絶縁性能を満たすものとして扱ってよいとされている。\nなお、電線を 1 本だけクランプすると、その線に流れる負荷電流が測定される。負荷電流と漏えい電流のどちらを測りたいかで、はさむ本数が変わる。\n【図解】クランプメータのはさみ方\n　測定したい量｜はさむ電線｜示す値\n　負荷電流｜1 本だけ｜その線の電流\n　漏えい電流｜すべて一括★｜行きと帰りの差\n　判定基準｜漏えい電流｜1 mA 以下\n　⇒ 漏電遮断器の零相変流器と同じ原理\n　⚠ 1 本だけはさむと漏えい電流にはならない',
    difficulty: 'standard',
