    explanation: '指示電気計器の階級は、最大目盛に対する許容差の百分率を表す。\n式：許容差＝最大目盛×階級÷100\n代入：許容差＝300×1.5÷100\n答え：±4.5 V\nこの許容差は、指示値がいくつであっても変わらない。300 V を指示しているときも、50 V を指示しているときも、誤差は最大 ±4.5 V である。したがって、指示値が小さいほど相対的な誤差の割合は大きくなる。\n50 V を指示している場合の相対誤差は 4.5÷50＝9 % にもなる。同じ計器で 300 V を測れば 1.5 % である。このことから、測定値が最大目盛に近くなるレンジを選ぶべきであることがわかる。目安として、最大目盛の 3 分の 2 以上の範囲で使うのがよいとされる。\n複数のレンジを持つ計器では、まず大きいレンジで測って値の見当をつけ、次に適切なレンジに切り換えるのが正しい使い方である。\n【図解】許容差の計算と相対誤差\n　項目｜計算｜結果\n　許容差｜300×1.5÷100｜±4.5 V★\n　300 V 指示時の相対誤差｜4.5÷300｜1.5 %\n　50 V 指示時の相対誤差｜4.5÷50｜9 %\n　⇒ 最大目盛の 3 分の 2 以上で使うのが望ましい\n　⚠ 許容差は指示値ではなく最大目盛で決まる',
