    choices: [
      { key: 'A', text: '直流専用であり、電力量の測定に用いられる。', explanation: '誤り。電力量計に用いられるのは交流専用の誘導形である。' },
      { key: 'B', text: '交流専用であり、商用周波数の電圧測定にのみ用いられる。', explanation: '誤り。熱電形は交直両用であり、高周波の測定にも使える。' },
      { key: 'C', text: '整流器を用いて交流を測定する計器である。', explanation: '誤り。整流器を用いるのは整流形である。熱電形は熱線と熱電対を用いる。' },
      { key: 'D', text: '交直両用であり、高周波の測定にも用いることができる。', explanation: '正しい。電流による発熱を熱電対で電圧に変換して測定するため、周波数の影響を受けにくい。' },
    ],
    correctKey: 'D',
    explanation: '熱電形計器は、測定する電流を熱線に流して発熱させ、その熱を熱電対で起電力に変換し、可動コイル形の機構で指示させる計器である。発熱量は電流の 2 乗に比例するので、交流でも直流でも測定でき、実効値を指示する。周波数の影響を受けにくいため、高周波の測定にも用いることができる。\n主な指示計器の種類と特徴を整理すると次のようになる。可動コイル形は直流専用で平均値を指示する。可動鉄片形は交流用で実効値を指示し、商用周波数の電圧計や電流計に広く使われる。電流力計形は交直両用で電力計に用いられる。誘導形は交流専用で電力量計に用いられる。整流形は交流を整流して測定し、正弦波の実効値に換算した目盛が振られている。静電形は高電圧の測定に用いられる。\nこの分類は毎年のように出題されるので、種類と使用電源と用途の 3 点をセットで覚える。\n【図解】指示計器の分類まとめ\n　種類｜使用電源｜おもな用途\n　熱電形｜交直両用★｜高周波の測定\n　電流力計形｜交直両用｜電力計\n　誘導形｜交流専用｜電力量計\n　⇒ 可動コイル形は直流、可動鉄片形は交流\n　⚠ 種類と用途の組合せを取り違えないこと',
    difficulty: 'basic',
