    correctKey: 'A',
    explanation: '絶縁抵抗計には、L 端子（ライン、線路側）と E 端子（アース、接地側）があり、機種によっては G 端子（ガード）も備えている。電線と大地間の絶縁抵抗を測るときは、L 端子を被測定電路に、E 端子を接地線または接地極に接続する。電線相互間を測るときは、一方の電線に L 端子、他方に E 端子を接続する。\n測定は必ず停電状態で行う。測定中は内部で数百ボルトの直流電圧が発生しているので、測定端子や電路に触れてはならない。測定後は電路に電荷が残るので、放電させてから作業する。\n低圧電路の絶縁抵抗の基準値は、対地電圧 150 V 以下で 0.1 MΩ 以上、使用電圧 300 V 以下でその他のもので 0.2 MΩ 以上、300 V を超えるもので 0.4 MΩ 以上である。\n測定が困難な場合は、漏えい電流が 1 mA 以下であることを確認する方法でもよい。\n【図解】絶縁抵抗計の端子と接続\n　端子｜記号｜接続先\n　ライン｜L｜被測定電路★\n　アース｜E｜接地線または大地\n　ガード｜G｜表面漏れ電流の除去\n　⇒ 電線相互間は L と E を各電線に接続する\n　⚠ 測定中は端子に触れないこと',
