    correctKey: 'C',
    explanation: 'D 種接地工事の接地抵抗値は原則として 100 Ω 以下である。ただし、当該電路に地絡を生じた場合に 0.5 秒以内に自動的に電路を遮断する装置（漏電遮断器）を施設するときは、500 Ω 以下に緩和される。\n本問では 0.3 秒で動作する漏電遮断器が施設されており、0.5 秒以内という条件を満たしている。したがって 500 Ω 以下であればよく、測定値 120 Ω は適合と判定される。\nこの緩和規定は C 種接地工事にも同様に適用される。C 種は原則 10 Ω 以下であるが、0.5 秒以内に動作する漏電遮断器を施設する場合は 500 Ω 以下でよい。\nA 種接地工事は 10 Ω 以下で緩和規定はない。B 種接地工事は変圧器の高圧側の 1 線地絡電流によって計算される値である。\n【図解】接地工事の種類と接地抵抗値\n　種類｜原則｜漏電遮断器 0.5 秒以内\n　A 種｜10 Ω 以下｜緩和なし\n　C 種｜10 Ω 以下｜500 Ω 以下\n　D 種｜100 Ω 以下｜500 Ω 以下★\n　⇒ C 種と D 種だけが 500 Ω に緩和される\n　⚠ 0.5 秒を超える動作時間では緩和されない',
