    explanation: '力率は有効電力を皮相電力で割って求める。電圧計と電流計の指示の積が皮相電力、電力計の指示が有効電力である。\n手順1（皮相電力）：S＝V×I＝210×12＝2520 V·A\n手順2（力率）：cosθ＝P÷S＝2100÷2520\n答え：cosθ＝0.833＝約 83 %\n電圧計と電流計だけでは力率がわからないため、有効電力を求めることはできない。電力計を併用してはじめて力率が算出できる。この 3 つの計器を組み合わせる方法は、力率計がない場合の実用的な測定方法である。\n無効電力も求められる。Q＝√(S²－P²)＝√(2520²－2100²)＝√(6350400－4410000)＝√1940400＝1393 var である。\n三相回路の場合は皮相電力が S＝√3×V×I になるので、力率は cosθ＝P÷(√3×V×I) となる。単相と三相で分母が変わる点に注意する。\n【図解】3 つの計器から力率を求める\n　計器｜指示値｜意味\n　電圧計と電流計｜210 V、12 A｜皮相電力 2520 V·A\n　電力計｜2100 W｜有効電力\n　力率｜2100÷2520｜約 0.83★\n　⇒ 三相では分母に √3 を掛ける\n　⚠ 電圧計と電流計だけでは力率は求められない',
