    explanation: '単相 3 線式は、変圧器の二次側巻線の中点から中性線を引き出し、2 本の外側線と合わせて 3 本の電線で配電する方式である。外側線と中性線の間には 100 V、外側線相互間には 200 V が現れるため、1 つの引込みで電灯用の 100 V とエアコンや IH 調理器などの 200 V の両方が使える。現在の一般住宅ではこの方式が標準である。\n単相 2 線式と比べた利点として、同じ電力を送る場合の電流が半分になるため、電圧降下と電力損失を小さくできることが挙げられる。\n注意点として、中性線には過電流遮断器を施設してはならない。中性線が先に遮断されると、負荷が不平衡な場合に軽負荷側へ過大な電圧が加わり、機器を焼損するおそれがあるためである。\n【図解】単相 3 線式で得られる電圧\n　接続する 2 点｜電圧｜おもな用途\n　外側線と中性線｜100 V｜電灯、一般コンセント\n　外側線相互間｜200 V★｜エアコン、IH 調理器\n　中性線と大地｜ほぼ 0 V｜B 種接地されている\n　⇒ 1 つの引込みで 2 種類の電圧が使える\n　⚠ 中性線に過電流遮断器を設けてはならない',
