    explanation: '単相 2 線式は、2 本の電線で単相交流を送る最も基本的な配電方式である。小規模な電灯負荷や、単相 3 線式の分岐回路として使われる。一方の電線は接地側電線（中性線側）で、B 種接地工事が施された変圧器の接地側につながっている。\n電圧降下は、行きの電線と帰りの電線の両方で生じるため、電線 1 本の抵抗を R、負荷電流を I とすると e＝2IR となる。\n例：電線 1 本の抵抗 0.1 Ω、負荷電流 10 A のとき\n式：e＝2IR\n代入：e＝2×10×0.1\n答え：e＝2 V\n配電方式ごとに係数が異なる点が重要である。単相 2 線式は 2、単相 3 線式（外側線と中性線の間）は 1、三相 3 線式は √3 である。\n【図解】配電方式と電圧降下の式\n　方式｜電圧降下の式｜係数\n　単相 2 線式｜e＝2IR★｜2\n　単相 3 線式｜e＝IR｜1\n　三相 3 線式｜e＝√3IR｜約 1.73\n　⇒ R は電線 1 本あたりの抵抗である\n　⚠ 係数を取り違えると答えが大きくずれる',
