    explanation: '中性線が断線すると、2 つの 100 V 負荷が外側線間の 200 V に対して直列に接続された状態になる。直列回路では電圧が抵抗の比に応じて分配されるため、抵抗の大きい負荷に高い電圧が加わる。負荷の抵抗は R＝V²÷P なので、消費電力が小さいほど抵抗が大きい。したがって軽負荷側に高い電圧が加わることになる。\n例：100 V・500 W（20 Ω）と 100 V・100 W（100 Ω）の場合\n合計抵抗：120 Ω\n100 W 側の電圧：200×100÷120＝167 V\n500 W 側の電圧：200×20÷120＝33 V\n定格 100 V の機器に 167 V が加わるため、100 W 側の機器は焼損する。テレビやパソコンなど消費電力の小さい機器が被害を受けやすい。\nこの事故を防ぐため、中性線には過電流遮断器を施設してはならず、接続部は確実に施工しなければならない。\n【図解】中性線断線時の電圧分配（500 W と 100 W）\n　負荷｜抵抗｜加わる電圧\n　100 W（軽負荷）｜100 Ω｜167 V★\n　500 W（重負荷）｜20 Ω｜33 V\n　合計｜120 Ω｜200 V\n　⇒ 消費電力が小さい機器ほど危険\n　⚠ 重負荷側に過電圧が加わると誤解しない',
