    explanation: '単相 2 線式の配線の電力損失は、電線 2 本分を考えて P＝2I²R で求める。\n式：P＝2×I²×R\n代入：P＝2×10²×0.2＝2×100×0.2\n答え：P＝40 W\n同じ条件での電圧降下は e＝2IR＝2×10×0.2＝4 V である。電源電圧 100 V なら負荷端は 96 V となる。\n損失 40 W を電圧降下から確認することもできる。電圧降下 4 V に電流 10 A を掛けると 4×10＝40 W となり一致する。配線の損失は、電圧降下と電流の積としても求められる。\nこの 40 W は熱として失われるだけで何の仕事もしない。24 時間連続で使えば 0.96 kW·h の無駄になる。損失を減らすには電線を太くするか、電圧を高くして電流を減らす。\n【図解】単相 2 線式の損失（I＝10 A、R＝0.2 Ω）\n　求め方｜式｜結果\n　損失の式から｜2I²R｜40 W★\n　電圧降下から｜e×I＝4×10｜40 W\n　1 日の損失電力量｜40×24÷1000｜0.96 kW·h\n　⇒ どちらの求め方でも同じ値になる\n　⚠ 電線 1 本分だけで計算しないこと',
