    explanation: '電圧降下は e＝kIR で電流に比例し、電力損失は P＝kI²R で電流の 2 乗に比例する。したがって電流を 2 分の 1 にすると、電圧降下は 2 分の 1、電力損失は 4 分の 1 になる。\n例：単相 2 線式、R＝0.1 Ω\nI＝20 A：e＝4 V、P＝80 W\nI＝10 A：e＝2 V、P＝20 W\n電圧降下は 4 V から 2 V へ半分、損失は 80 W から 20 W へ 4 分の 1 になっている。\nこの関係から、電流を減らす対策は損失の低減に特に有効だとわかる。供給電圧を 100 V から 200 V にすれば同じ電力で電流が半分になり、損失は 4 分の 1 になる。力率を改善しても同様の効果が得られる。\n設計では、電圧降下の基準（標準電圧の 2 % 以下）を満たすことが直接の目標になるが、その結果として損失も大きく低減される。\n【図解】電流を半分にしたときの変化\n　量｜比例関係｜変化\n　電圧降下｜電流に比例｜2 分の 1★\n　電力損失｜電流の 2 乗に比例｜4 分の 1★\n　発熱｜損失に比例｜4 分の 1\n　⇒ 200 V 化や力率改善は損失低減に有効\n　⚠ 両者の変化の割合が異なることに注意',
