    correctKey: 'B',
    explanation: '需要率は、設備容量に対する最大需要電力の割合である。\n式：需要率＝最大需要電力÷設備容量×100\n代入：60÷100×100\n答え：60 %\nこの需要家では、100 kW の設備を持っているが、実際に同時に使われる最大は 60 kW ということである。すべての機器が同時に全負荷運転されることはないため、こうした差が生じる。\n変圧器や幹線の容量を決める際には、この需要率を考慮する。設備容量 100 kW に対して 100 kW の変圧器を用意するのは過大であり、需要率を掛けた 60 kW 程度を基準に、余裕を見て選定する。\n需要率は建物の用途によって傾向があり、住宅は比較的低く、工場や店舗は高くなる。設計の目安として標準的な値が示されている。\n需要率が 100 % を超えることは原則としてない。計算結果が 100 % を超えたら、分子と分母を取り違えていないか確認する。\n【図解】需要率の計算と意味\n　項目｜値｜意味\n　設備容量｜100 kW｜機器の定格の合計\n　最大需要電力｜60 kW｜実際の最大\n　需要率｜60 %★｜同時に使われる割合\n　⇒ 変圧器容量の選定に用いる\n　⚠ 100 % を超えたら計算の向きを確認する',
