    explanation: '負荷率は、最大需要電力に対する平均需要電力の割合であり、設備がどれだけ平均的に（むらなく）使われているかを表す。\n式：負荷率＝平均需要電力÷最大需要電力×100\n代入：40÷80×100\n答え：50 %\n負荷率が高いほど、設備が常に高い割合で使われており効率がよいといえる。逆に負荷率が低いと、ピーク時に合わせて用意した設備が普段は遊んでいることを意味する。\n平均需要電力は、期間中の使用電力量を時間で割って求める。1 日の使用電力量が 960 kW·h であれば、平均需要電力は 960÷24＝40 kW である。\n期間の取り方によって日負荷率、月負荷率、年負荷率などと呼ばれる。負荷率が低い需要家に対しては、ピークを抑える運用（デマンド管理）が有効である。\n【図解】負荷率の計算\n　項目｜値｜備考\n　最大需要電力｜80 kW｜ピーク時\n　平均需要電力｜40 kW｜使用電力量÷時間\n　負荷率｜50 %★｜平均÷最大\n　⇒ 1 日 960 kW·h なら平均は 40 kW\n　⚠ 需要率の式と混同しないこと',
