    correctKey: 'D',
    explanation: '需要率は、設備容量に対する最大需要電力の割合である。すべての負荷設備が同時に全負荷で運転されることはまずないため、需要率は通常 100 % 以下になる。\n式：需要率＝最大需要電力÷設備容量×100 [%]\n例：設備容量 80 kW、最大需要電力 48 kW のとき\n代入：48÷80×100\n答え：60 %\nこの指標は、変圧器や幹線の容量を経済的に決めるために使われる。設備容量と同じ容量の変圧器を用意すると過大な投資になるため、需要率を掛けた値を基準にする。\n建物の用途によって標準的な需要率が示されており、住宅では比較的低く、工場や店舗では高くなる傾向がある。\n負荷率（平均÷最大、1 以下）、不等率（各最大の合計÷合成最大、1 以上）と合わせて、3 つの指標の定義を正確に区別しておくことが重要である。\n【図解】3 つの指標の定義と範囲\n　指標｜分子｜分母\n　需要率｜最大需要電力★｜設備容量★\n　負荷率｜平均需要電力｜最大需要電力\n　不等率｜各最大の合計｜合成最大需要電力\n　⇒ 需要率と負荷率は 1 以下、不等率は 1 以上\n　⚠ 3 つの式を取り違えると答えが合わない',
