    explanation: '日負荷率を求めるには、まず 1 日の使用電力量から平均需要電力を求める。\n手順1（平均需要電力）：480÷24＝20 kW\n手順2（負荷率）：20÷40×100\n答え：50 %\n負荷率は、設備がどれだけむらなく使われているかを表す。50 % ということは、平均するとピークの半分程度しか使われていないことを意味する。\n負荷率が低いと、ピークに合わせて用意した設備が普段は遊んでいることになり、設備の利用効率が悪い。契約電力は最大需要電力で決まるため、電気料金の面でも不利になる。負荷を時間的に分散させてピークを下げる運用（デマンド管理）が有効である。\n計算では、時間の扱いに注意する。1 日なら 24 時間、1 か月なら 24×日数 で割る。使用電力量 [kW·h] を時間 [h] で割ると平均電力 [kW] が得られる。\n【図解】日負荷率の計算\n　段階｜式｜結果\n　平均需要電力｜480÷24｜20 kW\n　最大需要電力｜与えられる｜40 kW\n　日負荷率｜20÷40×100｜50 %★\n　⇒ 負荷率が高いほど設備の利用効率がよい\n　⚠ 時間で割って平均電力にしてから比を取る',
