    explanation: '不等率は、各需要家（または各負荷群）の最大需要電力の合計を、それらを合わせた合成最大需要電力で割った値である。\n式：不等率＝各最大需要電力の合計÷合成最大需要電力\n各需要家のピークが発生する時刻はふつうずれているため、全体としての合成最大需要電力は各最大の単純な合計より小さくなる。したがって不等率は 1 以上になる。すべてのピークが完全に同時刻なら、合成最大が各最大の合計と等しくなり、不等率はちょうど 1 になる。\n例：A の最大 60 kW、B の最大 40 kW、合成最大 80 kW\n不等率：(60＋40)÷80＝1.25\n設計では、各最大需要電力の合計を不等率で割って合成最大需要電力を求め、それをもとに変圧器や幹線の容量を決める。不等率を考慮することで、設備を過大にせずにすむ。\n需要率と負荷率が 1 以下であるのに対し、不等率は 1 以上という点が明確な違いである。\n【図解】指標の値の範囲まとめ\n　指標｜値の範囲｜意味\n　需要率｜1 以下｜設備の同時使用の割合\n　負荷率｜1 以下｜使用のむらの少なさ\n　不等率｜1 以上★｜ピークのずれ具合\n　⇒ 合成最大＝各最大の合計÷不等率\n　⚠ 1 未満になったら分子と分母が逆',
