    explanation: '日負荷率は、1 日の平均需要電力を最大需要電力で割って求める。まず使用電力量から平均需要電力を計算する。\n手順1（平均需要電力）：1200÷24＝50 kW\n手順2（日負荷率）：50÷100×100\n答え：50 %\n平均が最大の半分ということは、1 日を通してピーク時の半分程度の電力しか使っていないことを意味する。\nもし 1 日中まったく変動なく 100 kW を使い続けたとすれば、使用電力量は 100×24＝2400 kW·h となり、負荷率は 100 % になる。実際にはそのような使い方は少なく、負荷率は 50 % 前後のことが多い。\n計算では、使用電力量 [kW·h] を時間 [h] で割って平均電力 [kW] にする段階を必ず踏む。ここを飛ばして電力量と電力を直接比べると誤る。\n負荷率が低い需要家では、ピークを下げる運用によって契約電力を減らし、電気料金を削減できる可能性がある。\n【図解】日負荷率の計算手順\n　段階｜式｜結果\n　平均需要電力｜1200÷24｜50 kW\n　最大需要電力｜与えられる｜100 kW\n　日負荷率｜50÷100×100｜50 %★\n　⇒ 24 時間一定なら 2400 kW·h で負荷率 100 %\n　⚠ 電力量と電力を直接比べないこと',
