    correctKey: 'C',
    explanation: '8 m 以下の位置に過電流遮断器を施設するには、分岐電線の許容電流が幹線の過電流遮断器の定格電流の 35 % 以上である必要がある。\n式：必要な許容電流＝幹線の遮断器定格×0.35\n代入：200×0.35\n答え：70 A 以上\nもし距離の制限をなくしたいなら、55 % 以上が必要なので 200×0.55＝110 A 以上の許容電流が必要になる。逆に、分岐電線の許容電流が 70 A 未満であれば、3 m 以下の位置に施設しなければならない。\nこの種の問題では、割合から必要な許容電流を逆算する形式もよく出る。0.35 と 0.55 という係数を掛ける計算を確実にできるようにしておく。\n選定にあたっては、70 A 以上の許容電流を持つ電線を選ぶ。600 V ビニル絶縁電線なら 22 mm²（許容電流 76 A）などが候補になるが、電流減少係数も考慮する必要がある。\n【図解】幹線の遮断器 200 A での必要許容電流\n　施設位置｜必要な割合｜必要な許容電流\n　3 m 以下｜制限なし｜任意\n　8 m 以下｜35 % 以上｜70 A★\n　制限なし｜55 % 以上｜110 A\n　⇒ 距離を延ばすほど太い電線が必要になる\n　⚠ 0.35 と 0.55 を取り違えないこと',
    difficulty: 'standard',
