    correctKey: 'A',
    explanation: '30 A の分岐回路には、直径 2.6 mm 以上（またはより線で断面積 5.5 mm² 以上）の電線を使用しなければならない。直径 2.0 mm の電線の許容電流は 35 A だが、規定として 2.6 mm 以上と定められているため、2.0 mm の使用は認められない。\n各分岐回路の正しい組合せは次のとおりである。\n15 A：電線 1.6 mm 以上、コンセント 15 A 以下\n20 A 配線用遮断器：電線 1.6 mm 以上、コンセント 20 A 以下\n20 A ヒューズ：電線 2.0 mm 以上、コンセント 20 A\n30 A：電線 2.6 mm 以上、コンセント 20 A 以上 30 A 以下\n40 A：電線 8 mm² 以上、コンセント 30 A 以上 40 A 以下\n50 A：電線 14 mm² 以上、コンセント 40 A 以上 50 A 以下\nこの表は毎年出題される最重要項目である。遮断器の定格、電線の太さ、コンセントの定格の 3 つがすべて条件を満たしているかを確認する。\n【図解】組合せの確認手順\n　確認項目｜本問の選択肢 A｜判定\n　電線の太さ｜2.0 mm｜2.6 mm 以上が必要★\n　コンセント｜30 A｜20 A 以上 30 A 以下で適合\n　総合判定｜電線が不足｜不適切\n　⇒ 3 つの要素すべてを確認する必要がある\n　⚠ 1 つでも条件を外れれば不適切になる',
    difficulty: 'advanced',
