    correctKey: 'D',
    explanation: '金属管や合成樹脂管などに複数の絶縁電線を収めると、電線どうしが互いの熱を受け、また管の中で放熱が妨げられるため、電線の温度が上がりやすくなる。そのため、収める本数に応じて許容電流を低減する必要がある。この低減の割合が電流減少係数である。\n同一管内の電線数と電流減少係数は次のとおりである。\n3 本以下：0.70\n4 本：0.63\n5 本から 6 本：0.56\n7 本から 15 本：0.49\n例：直径 1.6 mm（許容電流 27 A）を 3 本収める場合\n式：許容電流＝27×0.70\n答え：18.9 A\n本数が多いほど係数が小さくなり、実際に流せる電流が減る。設計では、収める本数を決めたうえで係数を掛け、必要な電流を流せる太さを選定する。\nなお、接地線や中性線で常時電流が流れないものは、電線数に数えない場合がある。\n【図解】同一管内の電線数と電流減少係数\n　電線数｜電流減少係数｜1.6 mm の許容電流\n　3 本以下｜0.70★｜18.9 A\n　4 本｜0.63｜17.0 A\n　5 本から 6 本｜0.56｜15.1 A\n　⇒ 本数が増えるほど放熱が悪くなる\n　⚠ 電圧降下の対策とは別の概念である',
