    explanation: '絶縁電線に許容電流を超える電流を流し続けると、ジュール熱によって電線の温度が上がり、絶縁物が許容温度を超えて劣化する。600 V ビニル絶縁電線の最高許容温度は 60 ℃ である。\n絶縁物が劣化すると、ひび割れや軟化が生じて絶縁性能が低下し、短絡や地絡を引き起こす。最悪の場合は電線が発火して火災につながる。\nまた、温度が上がると金属導体の抵抗が増えるため、電圧降下と電力損失がさらに増加し、温度がいっそう上がるという悪循環になる。\nこれを防ぐため、分岐回路には過電流遮断器を施設し、電線の許容電流を超える電流が流れ続けないようにしている。過電流遮断器の定格電流は、電線の許容電流（電流減少係数を考慮した値）以下でなければならない。\n設計では、許容電流、電流減少係数、周囲温度の 3 つを考慮して電線の太さを決める。\n【図解】許容電流を超えたときの連鎖\n　段階｜現象｜結果\n　1｜ジュール熱の増加｜温度上昇\n　2｜絶縁物の劣化｜絶縁性能の低下★\n　3｜短絡や地絡｜焼損、火災\n　⇒ 過電流遮断器がこれを防いでいる\n　⚠ 遮断器の定格は電線の許容電流以下にする',
