    correctKey: 'A',
    explanation: '600 V ビニル絶縁電線（IV）の最高許容温度は 60 ℃ である。許容電流は、周囲温度 30 ℃ の条件で連続して電流を流したときに、導体の温度がこの 60 ℃ を超えない値として定められている。\n絶縁物の種類によって最高許容温度は異なる。架橋ポリエチレン絶縁電線（IC）は 90 ℃、EP ゴム絶縁電線は 80 ℃ 程度である。耐熱性の高い絶縁物を用いれば、同じ太さでもより大きな電流を流せる。\n周囲温度が 30 ℃ を超える場所では、許容電流を低減する必要がある。温度が高いと、同じ電流でも導体の温度が許容温度に達しやすくなるためである。\nまた、管に複数の電線を収める場合は電流減少係数を掛ける。放熱条件が悪くなり温度が上がりやすくなるためである。\nこのように、許容電流は導体の太さだけでなく、絶縁物の種類、周囲温度、収容本数によって決まる。\n【図解】絶縁物の種類と最高許容温度\n　絶縁物｜略号｜最高許容温度\n　ビニル｜IV｜60 ℃★\n　架橋ポリエチレン｜IC｜90 ℃\n　基準となる周囲温度｜－｜30 ℃\n　⇒ 耐熱性が高いほど大きな電流を流せる\n　⚠ 周囲温度 30 ℃ と最高許容温度を混同しない',
