    correctKey: 'A',
    explanation: '三相 200 V の回路は、使用電圧が 300 V 以下であるが対地電圧が 150 V を超えるため、絶縁抵抗値は 0.2 MΩ 以上でなければならない。測定値 0.15 MΩ はこれを下回るので不適合である。\n判定の手順は次のとおりである。\n手順1（使用電圧の確認）：200 V なので 300 V 以下\n手順2（対地電圧の確認）：150 V を超える\n手順3（適用される基準）：0.2 MΩ 以上\n手順4（判定）：0.15 MΩ ＜ 0.2 MΩ なので不適合\n不適合の場合は、絶縁不良の箇所を特定して補修しなければならない。回路を区分して測定範囲を絞り込む、機器を取り外して電路だけを測定する、といった方法で原因を探る。\n仮に単相 100 V の回路であれば基準は 0.1 MΩ なので、0.15 MΩ は適合となる。同じ測定値でも回路の電圧によって判定が変わる点が重要である。\n【図解】同じ 0.15 MΩ でも判定が変わる\n　回路｜基準値｜判定\n　単相 100 V｜0.1 MΩ｜適合\n　三相 200 V｜0.2 MΩ｜不適合★\n　400 V 級｜0.4 MΩ｜不適合\n　⇒ まず適用される基準値を確定させる\n　⚠ 基準未満のまま使用してはならない',
    difficulty: 'advanced',
