    correctKey: 'B',
    explanation: '電気設備技術基準の解釈では、使用電圧が 60 V を超える低圧の機械器具であって金属製の外箱を有するものに電気を供給する電路には、地絡を生じたときに自動的に電路を遮断する装置（漏電遮断器）を施設しなければならないと定められている。\n金属製外箱を持つ機器は、内部で漏電すると外箱に電圧が現れ、触れた人が感電する危険がある。接地工事によって対地電圧を下げるとともに、漏電遮断器で電路を遮断することで安全を確保する。\n一方、次のような場合には省略できる。\n機械器具を乾燥した場所に施設する場合\n対地電圧が 150 V 以下の機械器具を水気のある場所以外に施設する場合\n二重絶縁構造の機械器具を施設する場合\n二次側 300 V 以下、3 kV·A 以下の絶縁変圧器を施設し、二次側を非接地とする場合\nC 種または D 種接地工事の接地抵抗値が 3 Ω 以下の場合\n施設義務と省略条件をセットで覚える。\n【図解】漏電遮断器の施設と省略\n　区分｜内容\n　施設が必要｜60 V 超の低圧、金属製外箱あり★\n　省略できる例｜乾燥した場所、二重絶縁構造\n　省略できる例｜接地抵抗 3 Ω 以下\n　⇒ 感電の危険の大きさで判断される\n　⚠ 水気のある場所では省略しにくい',
